#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Cat {
protected:
    string name;
    int age;
public:
    Cat(string n, int a) : name(n), age(a) {}
    void greet() {
        cout << "我是" << name << "，今年 " << age << " 岁喵" << endl;
    }
};

int main() {
    vector<Cat> roster;
    vector<int> keys = {1, 0, 1};

    for (int cmd : keys) {
        if (cmd == 0) {
            cout << "收摊喵，今天登记了 " << roster.size() << " 只" << endl;
            break;
        } else if (cmd == 1) {
            roster.push_back(Cat("{name}", 3));
            cout << "登记了一只，名册上现在 " << roster.size() << " 只" << endl;
        }
    }
    cout << "号码走完了，名册上 " << roster.size() << " 只" << endl;
    return 0;
}
